fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    // Pre-allocate the result vector with the same length as `a`
    let mut result: Vec<i32> = Vec::with_capacity(n);

    // Loop from 0 up to n, pushing a `1` in each iteration
    let mut i = 0;
    while i < n {
        result.push(1);
        i += 1;
    }

    result
}

